import {
  createContext,
  createEffect,
  createSignal,
  onCleanup,
  onMount,
  useContext,
  type ParentComponent,
  type Accessor,
} from "solid-js";

export type Theme = "light" | "dark" | "system";

export interface ThemeProviderProps {
  /** Initial default theme if no saved preference is found in localStorage */
  defaultTheme?: Theme;
  /** Key used to store theme preference in localStorage */
  storageKey?: string;
}

interface ThemeProviderContextValue {
  /** Current requested theme state ("light", "dark", or "system") */
  theme: Accessor<Theme>;
  /** Function to update the active theme preference */
  setTheme: (theme: Theme) => void;
}

const ThemeProviderContext = createContext<ThemeProviderContextValue>();

/**
 * Context provider managing application dark/light/system theme state and HTML root classes.
 */
export const ThemeProvider: ParentComponent<ThemeProviderProps> = (props) => {
  const storageKey = props.storageKey || "nikala-theme";
  const defaultTheme = props.defaultTheme || "system";

  // Safely read initial theme from localStorage if running in browser context
  const getInitialTheme = (): Theme => {
    if (typeof window === "undefined") return defaultTheme;
    try {
      const saved = localStorage.getItem(storageKey);
      if (saved === "light" || saved === "dark" || saved === "system") {
        return saved;
      }
    } catch {
      // Ignore localStorage access errors
    }
    return defaultTheme;
  };

  const [theme, setThemeSignal] = createSignal<Theme>(getInitialTheme());

  // Applies or removes .dark and .light classes on document.documentElement (<html>)
  const applyTheme = (targetTheme: Theme) => {
    if (typeof window === "undefined") return;

    const root = document.documentElement;
    root.classList.remove("light", "dark");

    if (targetTheme === "system") {
      const systemIsDark = window.matchMedia("(prefers-color-scheme: dark)").matches;
      root.classList.add(systemIsDark ? "dark" : "light");
    } else {
      root.classList.add(targetTheme);
    }
  };

  // Reactively apply theme changes and store selection in localStorage
  createEffect(() => {
    const currentTheme = theme();
    applyTheme(currentTheme);

    if (typeof window !== "undefined") {
      try {
        localStorage.setItem(storageKey, currentTheme);
      } catch {
        // Ignore localStorage write errors
      }
    }
  });

  onMount(() => {
    if (typeof window === "undefined") return;

    // Real-time listener for OS system theme preference changes using MediaQueryListEvent
    const mediaQuery = window.matchMedia("(prefers-color-scheme: dark)");

    const handleSystemChange = (e: MediaQueryListEvent) => {
      if (theme() === "system") {
        const root = document.documentElement;
        root.classList.remove("light", "dark");
        root.classList.add(e.matches ? "dark" : "light");
      }
    };

    if (mediaQuery.addEventListener) {
      mediaQuery.addEventListener("change", handleSystemChange);
    } else if ("addListener" in mediaQuery) {
      (mediaQuery as any).addListener(handleSystemChange);
    }

    onCleanup(() => {
      if (mediaQuery.removeEventListener) {
        mediaQuery.removeEventListener("change", handleSystemChange);
      } else if ("removeListener" in mediaQuery) {
        (mediaQuery as any).removeListener(handleSystemChange);
      }
    });
  });

  const setTheme = (newTheme: Theme) => {
    setThemeSignal(newTheme);
  };

  const value: ThemeProviderContextValue = {
    theme,
    setTheme,
  };

  return (
    <ThemeProviderContext.Provider value={value}>
      {props.children}
    </ThemeProviderContext.Provider>
  );
};

/**
 * Accesses Nikala UI theme state and update functions.
 */
export function useTheme(): ThemeProviderContextValue {
  const context = useContext(ThemeProviderContext);
  if (!context) {
    throw new Error("useTheme must be used within a ThemeProvider");
  }
  return context;
}

import { splitProps, type Component } from "solid-js";
import { useTheme } from "../../providers/theme-provider";
import { Button } from "./button";
import {
  DropdownMenu,
  DropdownMenuTrigger,
  DropdownMenuContent,
  DropdownMenuItem,
} from "./dropdown-menu";
import { cn } from "@/lib/cn";

export interface ThemeToggleProps {
  class?: string;
}

/**
 * Interactive UI dropdown button component for switching Nikala UI application themes.
 */
export const ThemeToggle: Component<ThemeToggleProps> = (props) => {
  const [local] = splitProps(props, ["class"]);
  const { setTheme } = useTheme();

  return (
    <DropdownMenu placement="bottom-end">
      <DropdownMenuTrigger
        as={Button}
        variant="outline"
        size="icon"
        class={cn("relative h-9 w-9 cursor-pointer", local.class)}
      >
        {/* Sun Icon (Visible in Light Mode) */}
        <svg
          class="h-4 w-4 rotate-0 scale-100 transition-all dark:-rotate-90 dark:scale-0"
          viewBox="0 0 24 24"
          fill="none"
          stroke="currentColor"
          stroke-width="2"
        >
          <circle cx="12" cy="12" r="4" />
          <path d="M12 2v2M12 20v2M4.93 4.93l1.41 1.41M17.66 17.66l1.41 1.41M2 12h2M20 12h2M6.34 17.66l-1.41 1.41M18.36 5.64l1.41-1.41" />
        </svg>

        {/* Moon Icon (Visible in Dark Mode) */}
        <svg
          class="absolute h-4 w-4 rotate-90 scale-0 transition-all dark:rotate-0 dark:scale-100"
          viewBox="0 0 24 24"
          fill="none"
          stroke="currentColor"
          stroke-width="2"
        >
          <path d="M12 3a6 6 0 0 0 9 9 9 0 1 1-9-9Z" />
        </svg>

        <span class="sr-only">Toggle theme</span>
      </DropdownMenuTrigger>

      <DropdownMenuContent>
        <DropdownMenuItem onClick={() => setTheme("light")}>
          <svg class="mr-2 h-4 w-4" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
            <circle cx="12" cy="12" r="4" />
            <path d="M12 2v2M12 20v2M4.93 4.93l1.41 1.41M17.66 17.66l1.41 1.41M2 12h2M20 12h2M6.34 17.66l-1.41 1.41M18.36 5.64l1.41-1.41" />
          </svg>
          Light
        </DropdownMenuItem>

        <DropdownMenuItem onClick={() => setTheme("dark")}>
          <svg class="mr-2 h-4 w-4" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
            <path d="M12 3a6 6 0 0 0 9 9 9 9 0 1 1-9-9Z" />
          </svg>
          Dark
        </DropdownMenuItem>

        <DropdownMenuItem onClick={() => setTheme("system")}>
          <svg class="mr-2 h-4 w-4" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
            <rect width="20" height="14" x="2" y="3" rx="2" />
            <line x1="8" x2="16" y1="21" y2="21" />
            <line x1="12" x2="12" y1="17" y2="21" />
          </svg>
          System
        </DropdownMenuItem>
      </DropdownMenuContent>
    </DropdownMenu>
  );
};
